        title: "render() y get_object_or_404()",
        code: true,
        mainFile: "miapp/views.py",
        django: "from django.shortcuts import get_object_or_404, render\n\nfrom .models import Pregunta\n\n\ndef lista(request):\n    return render(request, 'miapp/lista.html', {'preguntas': Pregunta.objects.all()})\n\n\ndef detalle(request, id):\n    pregunta = get_object_or_404(Pregunta, id=id)   # 404 si no existe\n    return render(request, 'miapp/detalle.html', {'pregunta': pregunta})",
        files: {"django": {"miapp/urls.py": "from django.urls import path\n\nfrom . import views\n\nurlpatterns = [\n    path('preguntas/', views.lista, name='lista'),\n    path('preguntas/<int:id>/', views.detalle, name='detalle'),\n]\n", "miapp/models.py": "from django.db import models\n\n\nclass Pregunta(models.Model):\n    texto = models.CharField(max_length=200)\n\n    def __str__(self):\n        return self.texto\n\n\nclass Opcion(models.Model):\n    pregunta = models.ForeignKey(Pregunta, on_delete=models.CASCADE, related_name='opciones')\n    texto = models.CharField(max_length=200)\n    votos = models.IntegerField(default=0)\n\n    def __str__(self):\n        return self.texto\n", "miapp/templates/miapp/lista.html": "{% for pregunta in preguntas %}<p>{{ pregunta.id }}. {{ pregunta }}</p>{% endfor %}\n", "miapp/templates/miapp/detalle.html": "<h1>{{ pregunta }}</h1>\n{% for opcion in pregunta.opciones.all %}<li>{{ opcion }}: {{ opcion.votos }} votos</li>{% endfor %}\n"}},
        driver: "from miapp.models import Pregunta\n\npregunta = Pregunta.objects.create(texto='¿Qué lenguaje prefieres?')\npregunta.opciones.create(texto='Python', votos=5)\npregunta.opciones.create(texto='PHP', votos=3)\nPregunta.objects.create(texto='¿Qué editor usas?')\n\nfrom django.test import Client\n\nnavegador = Client()   # simula un navegador\n\nprint(navegador.get('/preguntas/').content.decode())\nprint(navegador.get('/preguntas/1/').content.decode())\nprint(navegador.get('/preguntas/99/').status_code)",
        output: { django: "<p>1. ¿Qué lenguaje prefieres?</p><p>2. ¿Qué editor usas?</p>\n\n<h1>¿Qué lenguaje prefieres?</h1>\n<li>Python: 5 votos</li><li>PHP: 3 votos</li>\n\n404" },
