        django: "from decimal import Decimal\n\nfrom miapp.models import Categoria, Producto\n\nperifericos = Categoria.objects.create(nombre='Periféricos')\npantallas = Categoria.objects.create(nombre='Pantallas')\nProducto.objects.create(nombre='Teclado', categoria=perifericos, precio=Decimal('120.00'), stock=10)\nProducto.objects.create(nombre='Mouse', categoria=perifericos, precio=Decimal('45.50'), stock=25)\nProducto.objects.create(nombre='Monitor 24\"', categoria=pantallas, precio=Decimal('650.00'), stock=4)\n\nconsulta = Producto.objects.filter(precio__gt=100).order_by('nombre')\nprint(consulta.query)          # el SQL que Django genera\n\n# raw() ejecuta SQL propio y devuelve objetos del modelo\nfor producto in Producto.objects.raw('SELECT * FROM miapp_producto WHERE stock < %s', [20]):\n    print(producto.nombre, producto.stock)",
        files: {"django": {"miapp/models.py": "from django.db import models\n\n\nclass Categoria(models.Model):\n    nombre = models.CharField(max_length=100)\n\n    def __str__(self):\n        return self.nombre\n\n\nclass Producto(models.Model):\n    nombre = models.CharField(max_length=100)\n    categoria = models.ForeignKey(Categoria, on_delete=models.CASCADE, related_name='productos')\n    precio = models.DecimalField(max_digits=8, decimal_places=2)\n    stock = models.PositiveIntegerField(default=0)\n\n    def __str__(self):\n        return self.nombre\n"}},
