        django: "import json\n\nfrom django.http import JsonResponse\nfrom django.views.decorators.csrf import csrf_exempt\nfrom django.views.decorators.http import require_http_methods\n\nTAREAS = [{'id': 1, 'texto': 'Aprender Django', 'hecha': False}]\n\n\n@csrf_exempt                       # una API suele autenticarse con tokens, no con CSRF\n@require_http_methods(['GET', 'POST'])\ndef tareas(request):\n    if request.method == 'POST':\n        datos = json.loads(request.body)\n        if not datos.get('texto'):\n            return JsonResponse({'error': 'Falta el texto'}, status=400)\n        tarea = {'id': len(TAREAS) + 1, 'texto': datos['texto'], 'hecha': False}\n        TAREAS.append(tarea)\n        return JsonResponse(tarea, status=201)\n    return JsonResponse({'tareas': TAREAS})",
