        code: true,
        django: "from decimal import Decimal\n\nfrom miapp.models import Categoria, Producto\n\nperifericos = Categoria.objects.create(nombre='Periféricos')\npantallas = Categoria.objects.create(nombre='Pantallas')\nProducto.objects.create(nombre='Teclado', categoria=perifericos, precio=Decimal('120.00'), stock=10)\nProducto.objects.create(nombre='Mouse', categoria=perifericos, precio=Decimal('45.50'), stock=25)\nProducto.objects.create(nombre='Monitor 24\"', categoria=pantallas, precio=Decimal('650.00'), stock=4)\n\nfrom django.db.models import F, Sum\n\n# 1. Productos de menos de 100 soles, del más barato al más caro\nfor producto in Producto.objects.filter(precio__lt=100).order_by('precio'):\n    print(producto.nombre, producto.precio)\n\n# 2. Valor total del inventario: precio × stock de cada producto\ntotal = Producto.objects.aggregate(total=Sum(F('precio') * F('stock')))['total']\nprint('Valor del inventario:', total)\n\n# 3. Productos con poco stock (menos de 5)\nprint('Reponer:', [p.nombre for p in Producto.objects.filter(stock__lt=5)])",
